const cells = new Map<string, Entity[]>();
const key = (cx: number, cy: number) => `${cx},${cy}`;
const step = (v: number) => Math.floor(v / 32);
function insert(e: Entity) { const k = key(step(e.x), step(e.y)); (cells.get(k) ?? cells.set(k, []).get(k)!).push(e); }
function near(x: number, y: number, r: number): Entity[] {
  const out: Entity[] = [];
  for (let cy = step(y - r); cy <= step(y + r); cy++)
    for (let cx = step(x - r); cx <= step(x + r); cx++)
      for (const e of cells.get(key(cx, cy)) ?? [])
        if ((e.x - x) ** 2 + (e.y - y) ** 2 <= r * r) out.push(e);
  return out;
}

